\chapter{Methodology}\label{chap:methodology}
We now formalize the pipeline introduced informally in Chapter 2.
Section~\ref{sec:model} introduces the latent variable model, and
Section~\ref{sec:inference} derives the variational objective.

\section{Model}\label{sec:model}
Let $x_i \in \mathbb{R}^d$ denote the $i$-th observation and
$z_i \in \mathbb{R}^k$ the corresponding latent code. We assume
\begin{equation}
  p(x_i \mid z_i) = \mathcal{N}(x_i; f_\theta(z_i), \sigma^2 I).
\end{equation}
The prior is a standard Gaussian, $p(z_i) = \mathcal{N}(0, I)$,
following the usual amortized-inference setup.

\section{Inference}\label{sec:inference}
We maximize the evidence lower bound
\begin{equation}
  \mathcal{L} = \mathbb{E}_{q_\phi} \left[
    \log p_\theta(x \mid z) \right] - \mathrm{KL}\left(
    q_\phi(z \mid x) \,\|\, p(z) \right).
\end{equation}
All experiments were run with three random seeds; error bars in
Figure~\ref{fig:ablation} show one standard deviation.

