package controller

import (
	"context"

	appsv1alpha1 "github.com/example/operator/pkg/apis/apps/v1alpha1"
)

const (
	finalizerName = "apps.example.com/cleanup"
)

// ensureFinalizer adds the cleanup finalizer if it is missing.
func ensureFinalizer(d *appsv1alpha1.Deployment) bool {
	if containsString(d.Finalizers, finalizerName) {
		return false
	}
	d.Finalizers = append(d.Finalizers, finalizerName)
	return true
}

func removeFinalizer(d *appsv1alpha1.Deployment) {
	out := []string{}
	for _, f := range d.Finalizers {
		if f != finalizerName {
			out = append(out, f)
		}
	}
	d.Finalizers = out
}

func containsString(list []string, s string) bool {
	for _, item := range list {
		if item == s {
			return true
		}
	}
	return false
}
